var analysisRepository = {
  async create(data) {
    const now = new Date;
    const [analysis] = await db.insert(exports_schema.analyses).values({
      ...data,
      createdAt: now,
      updatedAt: now
    }).returning();
    return analysis;
  },
  async findAll(search) {
    let query = db.select().from(exports_schema.analyses).orderBy(desc(exports_schema.analyses.updatedAt));
    if (search) {
      query = query.where(like(exports_schema.analyses.name, `%${search}%`));
    }
    return query;
  },
  async findActive() {
    return db.select().from(exports_schema.analyses).where(eq(exports_schema.analyses.status, "active")).orderBy(desc(exports_schema.analyses.updatedAt));
  },
  async findById(id) {
    const [analysis] = await db.select().from(exports_schema.analyses).where(eq(exports_schema.analyses.id, id)).limit(1);
    return analysis || null;
  },
  async update(id, data) {
    const [updated] = await db.update(exports_schema.analyses).set({
      ...data,
      updatedAt: new Date
    }).where(eq(exports_schema.analyses.id, id)).returning();
    return updated || null;
  },
  async delete(id) {
    await db.delete(exports_schema.analyses).where(eq(exports_schema.analyses.id, id));
    return true;
  },
  async count() {
    const [result] = await db.select({
      total: sql`count(*)::int`,
      active: sql`count(*) filter (where ${exports_schema.analyses.status} = 'active')::int`
    }).from(exports_schema.analyses);
    return result || { total: 0, active: 0 };
  }
};

