// src/clients/client.controller.ts
var clientController = new Elysia({ prefix: "/api/v1/clients" }).get("/", async () => {
  return getAllClients();
}, {
  detail: { tags: ["Clients"], summary: "List all clients" }
}).get("/vendors", async () => {
  const clients2 = await getAllClients();
  const availableClients = clients2.filter((c) => c.available);
  const vendors = availableClients.map((c) => ({
    id: c.name,
    displayName: c.displayName
  }));
  const modelsByVendor = {};
  for (const client2 of availableClients) {
    modelsByVendor[client2.name] = client2.models.map((m2) => ({
      id: m2.id,
      displayName: m2.name
    }));
  }
  return { vendors, modelsByVendor };
}, {
  detail: { tags: ["Clients"], summary: "List vendors and models" }
}).get("/:name", async ({ params, set: set2 }) => {
  try {
    const client2 = getClient(params.name);
    return {
      name: client2.name,
      displayName: client2.displayName,
      available: await client2.isAvailable(),
      models: client2.getModels()
    };
  } catch {
    set2.status = 404;
    return { error: `Client not found: ${params.name}` };
  }
}, {
  params: t.Object({ name: t.String() }),
  detail: { tags: ["Clients"], summary: "Get client details" }
}).get("/:name/models", ({ params, set: set2 }) => {
  try {
    const client2 = getClient(params.name);
    return client2.getModels();
  } catch {
    set2.status = 404;
    return { error: `Client not found: ${params.name}` };
  }
}, {
  params: t.Object({ name: t.String() }),
  detail: { tags: ["Clients"], summary: "List client models" }
}).get("/:name/status", async ({ params, set: set2 }) => {
  try {
    const client2 = getClient(params.name);
    return {
      name: client2.name,
      available: await client2.isAvailable()
    };
  } catch {
    set2.status = 404;
    return { error: `Client not found: ${params.name}` };
  }
}, {
  params: t.Object({ name: t.String() }),
  detail: { tags: ["Clients"], summary: "Check client status" }
});

// src/index.ts
var PORT = process.env.PORT ?? 3001;
var app = new Elysia().use(cors({
  origin: true,
  methods: ["GET", "POST", "PUT", "DELETE", "OPTIONS"],
  allowedHeaders: ["Content-Type", "X-API-Key", "X-Caller-Service"]
})).use(swagger({
  documentation: {
    info: {
      title: "Alysis API",
      version: "1.0.0",
      description: "AI Analysis Platform API"
    },
    tags: [
      { name: "Health", description: "Health check endpoint" },
      { name: "Apps", description: "App management" },
      { name: "Prompts", description: "Prompt version management" },
      { name: "Execution", description: "App execution" },
      { name: "Clients", description: "AI client information" },
      { name: "API Keys", description: "API key management" },
      { name: "Vendor Keys", description: "Vendor API key management" }
    ],
    components: {
      securitySchemes: {
        apiKey: {
          type: "apiKey",
          in: "header",
          name: "X-API-Key"
        }
      }
    },
    security: [{ apiKey: [] }]
  },
  path: "/docs",
  exclude: ["/docs", "/docs/*", "/api/health"]
})).use(staticPlugin({
  assets: "public",
  prefix: "/",
  indexHTML: true
})).use(healthController).use(clientController).use(analysisController).use(promptController).use(executionController).use(apiKeyController).use(vendorKeyController).listen(PORT);
